import java.io.*;
import java.util.*;

public class Main {
    static final InputStream IN = System.in;
    static final byte[] BUF = new byte[1 << 16];
    static int len, ptr;

    static int readByte() throws IOException {
        if (ptr == len) {
            len = IN.read(BUF, 0, BUF.length);
            ptr = 0;
            if (len <= 0) {
                len = 0;
                return -1;
            }
        }
        return BUF[ptr++];
    }

    static long nextLong() throws IOException {
        int c = readByte();
        while (c == ' ' || c == '\n' || c == '\r' || c == '\t') c = readByte();
        boolean neg = c == '-';
        if (neg) c = readByte();
        long v = 0;
        while (c >= '0' && c <= '9') {
            v = v * 10 + (c - '0');
            c = readByte();
        }
        return neg ? -v : v;
    }

    static int nextInt() throws IOException {
        return (int) nextLong();
    }

    static String next() throws IOException {
        int c = readByte();
        while (c == ' ' || c == '\n' || c == '\r' || c == '\t') c = readByte();
        StringBuilder sb = new StringBuilder();
        while (c > ' ') {
            sb.append((char) c);
            c = readByte();
        }
        return sb.toString();
    }

    public static void main(String[] args) throws IOException {
        int n = nextInt();
        long[] xs = new long[n], ys = new long[n];
        // row y -> {min x, max x}; column x -> {min y, max y}
        HashMap<Long, long[]> rows = new HashMap<>(), cols = new HashMap<>();
        for (int i = 0; i < n; i++) {
            long x = nextLong(), y = nextLong();
            xs[i] = x;
            ys[i] = y;
            long[] r = rows.get(y);
            if (r == null) rows.put(y, new long[] {x, x});
            else {
                r[0] = Math.min(r[0], x);
                r[1] = Math.max(r[1], x);
            }
            long[] c = cols.get(x);
            if (c == null) cols.put(x, new long[] {y, y});
            else {
                c[0] = Math.min(c[0], y);
                c[1] = Math.max(c[1], y);
            }
        }
        long answer = 0;
        for (int i = 0; i < n; i++) {
            long[] r = rows.get(ys[i]), c = cols.get(xs[i]);
            if (r[0] < xs[i] && xs[i] < r[1] && c[0] < ys[i] && ys[i] < c[1]) answer++;
        }
        System.out.println(answer);
    }
}

package main

import (
	"fmt"
	"io"
	"os"
)

var data []byte
var pos int

// token returns the next whitespace-separated token of stdin.
func token() []byte {
	for pos < len(data) && data[pos] <= ' ' {
		pos++
	}
	start := pos
	for pos < len(data) && data[pos] > ' ' {
		pos++
	}
	return data[start:pos]
}

func nextInt() int {
	b := token()
	neg := len(b) > 0 && b[0] == '-'
	if neg {
		b = b[1:]
	}
	v := 0
	for _, c := range b {
		v = v*10 + int(c-'0')
	}
	if neg {
		return -v
	}
	return v
}

func main() {
	data, _ = io.ReadAll(os.Stdin)
	n := nextInt()
	xs, ys := make([]int, n), make([]int, n)
	// row y -> {min x, max x}; column x -> {min y, max y}
	rows, cols := map[int][2]int{}, map[int][2]int{}
	for i := 0; i < n; i++ {
		x, y := nextInt(), nextInt()
		xs[i], ys[i] = x, y
		if r, ok := rows[y]; ok {
			rows[y] = [2]int{min(r[0], x), max(r[1], x)}
		} else {
			rows[y] = [2]int{x, x}
		}
		if c, ok := cols[x]; ok {
			cols[x] = [2]int{min(c[0], y), max(c[1], y)}
		} else {
			cols[x] = [2]int{y, y}
		}
	}
	answer := 0
	for i := 0; i < n; i++ {
		x, y := xs[i], ys[i]
		r, c := rows[y], cols[x]
		if r[0] < x && x < r[1] && c[0] < y && y < c[1] {
			answer++
		}
	}
	fmt.Println(answer)
}
